theme.css:
/* Strata by HTML5 UP | html5up.net | @ajlkn | CC BY 3.0.
 * Adapted for ImmichPager; composition, typography and accessibility modified. */
:scope { grid-template-columns:320px minmax(0,1fr); gap:48px; }
.ip-hero { background:#1f1815; color:#ffffff; padding:40px 32px; min-height:calc(100dvh - 64px); }
.ip-hero .ip-banner { position:absolute; inset:0; width:100%; height:100%; opacity:.3; }
.ip-hero .ip-header { position:relative; color:#ffffff; --pager-muted:#ffffff; z-index:1; text-align:right; }
.ip-hero .ip-navigation { border-color:#ffffff55; align-items:flex-end; }
.ip-title { font-weight:var(--pager-title-font-weight); line-height:1.5; letter-spacing:0; }
.ip-block { border-bottom:1px solid var(--pager-border); padding-block:32px; }
@media(max-width:760px) { :scope { display:block; padding:20px; } .ip-hero { min-height:320px; padding:32px 24px; } .ip-hero .ip-header { text-align:left; } .ip-hero .ip-navigation { align-items:flex-start; } }

.ip-description { opacity:1; }

.ip-albums:not(.tiles) .ip-album-info p { opacity:1; color:var(--pager-muted); }
.ip-albums.tiles .ip-album-info p { opacity:1; color:#ffffff; }
